    public record UpgradeDef(
        string Id, string Tower, int Path, string PathName, int Tier, string Name, int Cost,
        string Requires, string Status, bool IsTier5, bool CanonVerified,
        double DmgMult, int PierceAdd, double SpeedMult, double RangeAdd, double AoeMult,
        int StatusStacks, double EconMult, double AuraPct, int Summons, string Effect);

    public record TowerDef(string Id, string Replacement, int BaseCost, double BaseDamage,
        double BasePierce, double BaseAps, double BaseRange);

    public record HeroDef(string Replacement, string Vanilla, string Role, int Cost, string DesignBasis);

    public record HeroLevel(string Hero, int Level, int XpCumulative, double DmgMult,
        double SpeedMult, double RangeAdd, string Unlock, string Effect);

    /// <summary>Parsed, indexed view of the embedded data.</summary>
    public static class LimbusData
    {
        public static List<TowerDef> Towers { get; private set; } = new();
        public static List<UpgradeDef> Upgrades { get; private set; } = new();
        public static List<HeroDef> Heroes { get; private set; } = new();
        public static List<HeroLevel> HeroLevels { get; private set; } = new();
        public static JsonDocument Systems { get; private set; }
        public static Dictionary<string, UpgradeDef> UpgradeById { get; private set; } = new();

        static string S(JsonElement e, string n) => e.GetProperty(n).GetString();
        static int I(JsonElement e, string n) => (int)Math.Round(e.GetProperty(n).GetDouble());
        static double D(JsonElement e, string n) => e.GetProperty(n).GetDouble();

        public static void Load()
        {
            Systems = JsonDocument.Parse(EmbeddedData.SystemsJson);

            using var up = JsonDocument.Parse(EmbeddedData.UpgradesJson);
            Towers = up.RootElement.GetProperty("towers").EnumerateArray().Select(t => new TowerDef(
                S(t, "id"), S(t, "replacement"), I(t, "base_cost"), D(t, "base_damage"),
                D(t, "base_pierce"), D(t, "base_aps"), D(t, "base_range"))).ToList();

            Upgrades = up.RootElement.GetProperty("upgrades").EnumerateArray().Select(u => new UpgradeDef(
                S(u, "id"), S(u, "tower"), I(u, "path"), S(u, "path_name"), I(u, "tier"), S(u, "name"),
                I(u, "cost"), S(u, "requires"), S(u, "status"), u.GetProperty("is_tier5").GetBoolean(),
                u.GetProperty("canon_verified").GetBoolean(), D(u, "dmg_mult"), I(u, "pierce_add"),
                D(u, "speed_mult"), D(u, "range_add"), D(u, "aoe_mult"), I(u, "status_stacks"),
                D(u, "econ_mult"), D(u, "aura_pct"), I(u, "summons"), S(u, "effect"))).ToList();
            UpgradeById = Upgrades.ToDictionary(u => u.Id);

            using var he = JsonDocument.Parse(EmbeddedData.HeroesJson);
            Heroes = he.RootElement.GetProperty("heroes").EnumerateArray().Select(h => new HeroDef(
                S(h, "replacement"), S(h, "vanilla"), S(h, "role"), I(h, "cost"), S(h, "design_basis"))).ToList();
            HeroLevels = he.RootElement.GetProperty("levels").EnumerateArray().Select(l => new HeroLevel(
                S(l, "hero"), I(l, "level"), I(l, "xp_cumulative"), D(l, "dmg_mult"), D(l, "speed_mult"),
                D(l, "range_add"), S(l, "unlock"), S(l, "effect"))).ToList();
        }

        /// <summary>Returns human-readable problems; empty list = data is consistent.</summary>
        public static List<string> Validate()
        {
            var problems = new List<string>();
            var towerIds = Towers.Select(t => t.Id).ToHashSet();
            foreach (var u in Upgrades)
            {
                if (!towerIds.Contains(u.Tower)) problems.Add($"{u.Id}: unknown tower {u.Tower}");
                if (u.Requires != "none" && !UpgradeById.ContainsKey(u.Requires))
                    problems.Add($"{u.Id}: requires missing upgrade {u.Requires}");
            }
            foreach (var h in Heroes)
                if (HeroLevels.Count(l => l.Hero == h.Replacement) != 20)
                    problems.Add($"hero {h.Replacement}: expected 20 levels");
            return problems;
        }
    }

    public class LimbusMod : BloonsTD6Mod
    {
        public override void OnApplicationStart()
        {
            try
            {
                LimbusData.Load();
                ModHelper.Msg<LimbusMod>(
                    $"Loaded {LimbusData.Towers.Count} towers, {LimbusData.Upgrades.Count} upgrades, " +
                    $"{LimbusData.Heroes.Count} heroes, {LimbusData.HeroLevels.Count} hero levels.");
                foreach (var p in LimbusData.Validate())
                    ModHelper.Warning<LimbusMod>("Data check: " + p);
            }
            catch (Exception e)
            {
                ModHelper.Error<LimbusMod>("Failed to load embedded data: " + e);
            }
        }
        // TODO: applying the data to the game (renaming towers, changing upgrade models, adding heroes)
        // needs BTD6 game-model code that is not part of the JSON files.
    }
}
